mapper.select:
SELECT *,
       CASE WHEN api_key IS NOT NULL AND api_key != '' THEN 1 ELSE 0 END AS api_key_configured,
       CASE WHEN api_secret IS NOT NULL AND api_secret != '' THEN 1 ELSE 0 END AS api_secret_configured
FROM ${database.prefix.userms}hou_base_ai_config


        AND (provider_name LIKE CONCAT('%', #{param.keyword}, '%')
        OR model_name LIKE CONCAT('%', #{param.keyword}, '%'))


        AND provider_code = #{param.providerCode}


        AND is_enabled = #{param.isEnabled}


        AND status = #{param.status}


ORDER BY sort_order DESC, create_time DESC
